// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
//
// Hardware operation check: one short program that exercises each path a CKKS
// application takes through the haze backend, so a replay target (the local
// simulator, the Fog's FUNC_SIM, the Fog FPGA) can be checked in a single run.
//
// Each operation starts from fresh inputs and is declared an output, so haze
// records them as one program and a target that breaks one operation still
// reports on the others. Every result is compared with the same operation run by
// OpenFHE in this process, on the same context and keys:
//   ring-exact  every coefficient of every tower identical (needs OpenFHE built
//               with reduced noise, as FIDESlib's haze parity does)
//   decrypt     the first kCheck slots decrypt to within kTol of OpenFHE's
// An operation passes only when both hold.
//
// Operations, by the hardware path they exercise:
//   add              upload, data-format conversion, readback
//   pt_mult          ciphertext x plaintext (plaintext format conversion); under
//                    FLEXIBLEAUTO its rescale is deferred, so no rescale runs
//   pt_mult_rescale  two plaintext multiplies, so the first is rescaled
//   relin            ciphertext x ciphertext: key switching with the mult key
//   rot_1, rot_neg1, rot_4096   key switching with rotation keys
//   square_chain     repeated squaring down the modulus chain (every level's prime)
//   chebyshev_7      a degree-7 Chebyshev series (all of the above combined)
//
// Parameters: ring 2^16 (the only ring the Fog FPGA runs), depth 8, scale 42,
// first modulus 57, FLEXIBLEAUTO, 128-bit security.
//
// Usage: ./hw_ops_check [--cpu | --target=T] [--only=op[,op...]]
//   default     haze, replayed where FIDESLIB_HAZE_TARGET says (unset: local simulator)
//   --target=T  sets FIDESLIB_HAZE_TARGET=T; `fog submit` forwards its own --target
//   --cpu       FIDESlib's CPU backend (checks the check itself)
//   --only=...  record and check only these operations (a minimal trace for triage)
// Exit status 0 only when every operation passes.

#include <fideslib.hpp>
#include <Interop.hpp>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <functional>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using namespace fideslib;
using LbCt = lbcrypto::Ciphertext<lbcrypto::DCRTPoly>;

namespace {

constexpr uint32_t kRingDim = 65536;
constexpr uint32_t kDepth = 8;
constexpr uint32_t kScalingModSize = 42;
constexpr uint32_t kFirstModSize = 57;
constexpr int32_t kBigStep = 4096;
constexpr size_t kCheck = 16;     // slots compared after decryption
// Decrypt agreement. CKKS decryption adds fresh noise, which reaches ~5e-6 on
// square_chain at the bottom level; ring-exact is the precise check, this one
// only has to catch garbage.
constexpr double kTol = 1e-4;

// Number of differing coefficients across all towers, or SIZE_MAX when the two
// ciphertexts differ in shape (component or tower count).
size_t ring_diff(const LbCt& a, const LbCt& b) {
    const auto& ea = a->GetElements();
    const auto& eb = b->GetElements();
    if (ea.size() != eb.size()) return SIZE_MAX;
    size_t diffs = 0;
    for (size_t c = 0; c < ea.size(); ++c) {
        const auto& ta = ea[c].GetAllElements();
        const auto& tb = eb[c].GetAllElements();
        if (ta.size() != tb.size()) return SIZE_MAX;
        for (size_t t = 0; t < ta.size(); ++t) {
            const auto& va = ta[t].GetValues();
            const auto& vb = tb[t].GetValues();
            for (size_t i = 0; i < va.GetLength(); ++i) diffs += (va[i] != vb[i]);
        }
    }
    return diffs;
}

struct Case {
    std::string name;
    Ciphertext<DCRTPoly> got;  // FIDESlib, on the chosen backend
    LbCt oracle;               // OpenFHE, same inputs and keys
};

}  // namespace

int main(int argc, char* argv[]) {
    bool cpu = false;
    std::string target;
    std::vector<std::string> only;
    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        if (a == "--cpu") cpu = true;
        else if (a.rfind("--target=", 0) == 0) target = a.substr(9);
        else if (a.rfind("--only=", 0) == 0) {
            std::istringstream names(a.substr(7));
            for (std::string n; std::getline(names, n, ',');)
                if (!n.empty()) only.push_back(n);
        } else {
            std::cerr << "Usage: " << argv[0] << " [--cpu | --target=T] [--only=op[,op...]]" << std::endl;
            return 2;
        }
    }
    if (cpu && !target.empty()) {
        std::cerr << "--cpu and --target are exclusive: a target is where haze replays" << std::endl;
        return 2;
    }
    if (!target.empty()) setenv("FIDESLIB_HAZE_TARGET", target.c_str(), 1);
    const char* t = std::getenv("FIDESLIB_HAZE_TARGET");
    const std::string where = cpu ? "cpu" : std::string("haze, target ") + (t && *t ? t : "local");

    CCParams<CryptoContextCKKSRNS> parameters;
    parameters.SetSecurityLevel(HEStd_128_classic);
    parameters.SetRingDim(kRingDim);
    parameters.SetMultiplicativeDepth(kDepth);
    parameters.SetScalingModSize(kScalingModSize);
    parameters.SetFirstModSize(kFirstModSize);
    parameters.SetScalingTechnique(FLEXIBLEAUTO);
    parameters.SetBackend(cpu ? Backend::CPU : Backend::HAZE);
    parameters.SetReducedNoise(LinkedOpenFheReducedNoise());
    parameters.SetPlaintextAutoload(false);
    parameters.SetCiphertextAutoload(true);
    CryptoContext<DCRTPoly> cc = GenCryptoContext(parameters);
    cc->Enable(PKE);
    cc->Enable(KEYSWITCH);
    cc->Enable(LEVELEDSHE);
    cc->Enable(ADVANCEDSHE);

    auto keys = cc->KeyGen();
    cc->EvalMultKeyGen(keys.secretKey);
    cc->EvalRotateKeyGen(keys.secretKey, {1, -1, kBigStep});
    cc->LoadContext(keys.publicKey);

    // The OpenFHE context FIDESlib wraps: same parameters, same keys (the oracle).
    auto& lcc = std::any_cast<lbcrypto::CryptoContext<lbcrypto::DCRTPoly>&>(cc->host);
    const auto& lsk = std::any_cast<const lbcrypto::PrivateKey<lbcrypto::DCRTPoly>&>(keys.secretKey->pimpl);

    // Full-slot inputs, so a rotation by any step moves real data into the checked slots.
    // x stays near 1 so x^(2^7) is still well above the decryption noise.
    const size_t slots = kRingDim / 2;
    std::vector<double> x(slots), y(slots), w(slots);
    for (size_t i = 0; i < slots; ++i) {
        x[i] = 0.95 + 0.05 * std::fmod(0.618034 * i, 1.0);
        y[i] = 0.5 + 0.25 * std::sin(0.37 * i);
        w[i] = 0.75 + 0.2 * std::cos(0.11 * i);
    }
    Plaintext ptX = cc->MakeCKKSPackedPlaintext(x);
    Plaintext ptY = cc->MakeCKKSPackedPlaintext(y);
    Plaintext ptW = cc->MakeCKKSPackedPlaintext(w);
    auto ctX = cc->Encrypt(keys.publicKey, ptX);
    auto ctY = cc->Encrypt(keys.publicKey, ptY);
    // Fresh encryptions are host-resident, so their OpenFHE values are the inputs.
    const LbCt lX = ExportCiphertext(ctX);
    const LbCt lY = ExportCiphertext(ctY);
    const auto& lW = std::any_cast<const lbcrypto::Plaintext&>(ptW->host);

    std::function<double(double)> f = [](double v) { return std::tanh(v); };
    auto coeffs = CryptoContextImpl<DCRTPoly>::GetChebyshevCoefficients(f, -1.0, 1.0, 7);

    // Each operation as a builder, so --only records nothing it does not report.
    using Build = std::function<Case()>;
    const std::vector<std::pair<std::string, Build>> all = {
        {"add", [&] { return Case{"add", cc->EvalAdd(ctX, ctY), lcc->EvalAdd(lX, lY)}; }},
        {"pt_mult", [&] { return Case{"pt_mult", cc->EvalMult(ctX, ptW), lcc->EvalMult(lX, lW)}; }},
        {"pt_mult_rescale", [&] {
             return Case{"pt_mult_rescale", cc->EvalMult(cc->EvalMult(ctX, ptW), ptW),
                         lcc->EvalMult(lcc->EvalMult(lX, lW), lW)};
         }},
        {"relin", [&] { return Case{"relin", cc->EvalMult(ctX, ctY), lcc->EvalMult(lX, lY)}; }},
        {"rot_1", [&] { return Case{"rot_1", cc->EvalRotate(ctX, 1), lcc->EvalRotate(lX, 1)}; }},
        {"rot_neg1", [&] { return Case{"rot_neg1", cc->EvalRotate(ctX, -1), lcc->EvalRotate(lX, -1)}; }},
        {"rot_4096", [&] {
             return Case{"rot_4096", cc->EvalRotate(ctX, kBigStep), lcc->EvalRotate(lX, kBigStep)};
         }},
        {"square_chain", [&] {
             auto s = ctX;
             LbCt ls = lX;
             for (uint32_t k = 0; k + 1 < kDepth; ++k) {
                 s = cc->EvalMult(s, s);
                 ls = lcc->EvalMult(ls, ls);
             }
             return Case{"square_chain", s, ls};
         }},
        {"chebyshev_7", [&] {
             return Case{"chebyshev_7", cc->EvalChebyshevSeries(ctX, coeffs, -1.0, 1.0),
                         lcc->EvalChebyshevSeries(lX, coeffs, -1.0, 1.0)};
         }},
    };

    // Record the selected operations on the chosen backend, with their oracles.
    std::vector<Case> cases;
    for (const auto& [name, build] : all)
        if (only.empty() || std::find(only.begin(), only.end(), name) != only.end()) cases.push_back(build());
    if (cases.size() != (only.empty() ? all.size() : only.size())) {
        std::cerr << "--only names an unknown operation; known:";
        for (const auto& [name, build] : all) std::cerr << " " << name;
        std::cerr << std::endl;
        return 2;
    }

    // haze executes the whole program at the first readback, so declare every output
    // first, then read them all back before printing (the replay logs its own lines).
    for (auto& c : cases) cc->MarkOutput(c.got);
    for (auto& c : cases) cc->RecoverHostCiphertext(c.got);

    std::cout << "hw_ops_check: " << where << ", ring " << kRingDim << ", depth " << kDepth << std::endl;
    std::cout << std::left << std::setw(17) << "operation" << std::setw(30) << "ring vs OpenFHE"
              << std::setw(26) << "decrypt vs OpenFHE" << "verdict" << std::endl;
    int failures = 0;
    for (auto& c : cases) {
        const LbCt got = ExportCiphertext(c.got);

        const size_t d = ring_diff(got, c.oracle);
        const std::string ring = d == 0 ? "exact"
                               : d == SIZE_MAX ? "DIFFERENT SHAPE"
                               : std::to_string(d) + " coefficients differ";

        std::string dec;
        bool dec_ok = false;
        try {
            lbcrypto::Plaintext pg, po;
            lcc->Decrypt(lsk, got, &pg);
            lcc->Decrypt(lsk, c.oracle, &po);
            pg->SetLength(kCheck);
            po->SetLength(kCheck);
            const auto vg = pg->GetRealPackedValue();
            const auto vo = po->GetRealPackedValue();
            double worst = 0;
            for (size_t i = 0; i < kCheck; ++i) worst = std::max(worst, std::fabs(vg[i] - vo[i]));
            std::ostringstream os;
            os << "max diff " << std::scientific << std::setprecision(1) << worst;
            dec = os.str();
            dec_ok = worst <= kTol;
        } catch (const std::exception&) {
            dec = "UNDECODABLE";
        }

        const bool ok = d == 0 && dec_ok;
        failures += !ok;
        std::cout << std::left << std::setw(17) << c.name << std::setw(30) << ring << std::setw(26) << dec
                  << (ok ? "PASS" : "FAIL") << std::endl;
    }
    std::cout << (failures == 0 ? "ALL PASS" : std::to_string(failures) + " FAILED") << " (" << where << ")"
              << std::endl;
    return failures == 0 ? 0 : 1;
}
